import{c as s,Q as t,j as a,m as i}from"./chunks/framework.COywXlYp.js";const f=JSON.parse('{"title":"Version Naming Rules","description":"Introduction to ClickMouse version naming rules.","frontmatter":{"title":"Version Naming Rules","description":"Introduction to ClickMouse version naming rules.","layout":"doc"},"headers":[],"relativePath":"en/guide/version-naming.md","filePath":"en/guide/version-naming.md"}'),o={name:"en/guide/version-naming.md"};function n(r,e,l,p,c,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="version-naming-rules" tabindex="-1">Version Naming Rules <a class="header-anchor" href="#version-naming-rules" aria-label="Permalink to &quot;Version Naming Rules&quot;">​</a></h1><p>clickmouse version format is: <code>A.B.C.D[(alpha | beta |.dev | rc) E]</code></p><h2 id="official-versions" tabindex="-1">Official Versions <a class="header-anchor" href="#official-versions" aria-label="Permalink to &quot;Official Versions&quot;">​</a></h2><p>Official versions do not have .dev, alpha, beta, or rc suffixes.</p><p>A position represents major updates with code-level changes. For example, upgrading from 1.0 to 2.0 involves code refactoring.</p><p>B position represents regular updates, usually updating some major features.</p><p>C position represents fix updates, usually updating some small features and fixing some bugs.</p><p>D position represents version code, usually increments by 1 when A, B, C positions change. It is also possible that A, B, C positions do not change but D position increments by 1, representing emergency updates, usually fixing several major impact bugs.</p><h2 id="test-versions" tabindex="-1">Test Versions <a class="header-anchor" href="#test-versions" aria-label="Permalink to &quot;Test Versions&quot;">​</a></h2><p>Test versions have .dev, alpha, beta, or rc suffixes.</p><p>Usually the preceding <code>A.B.C.D</code> does not change within a testing cycle, representing the next version.</p><p><code>.dev</code> represents early development updates, features are unstable, many bugs, located in the early stage of version project.The new features in this phase will be put in the lab and turned off by default.</p><p><code>alpha</code> represents late development updates, features are incomplete, many bugs, located in the early stage of version project.The new features in this phase will be put in the lab and turned off by default.</p><p><code>beta</code> represents release testing updates, features are complete, few bugs, no new features will be added, located in the middle stage of version project. It is usually released in the middle of the development cycle and will gradually merge features from the lab.</p><p><code>rc</code> represents release candidate versions, features are complete, few bugs, will fix some important security issues or bugs, closest to official version, about to release official version, located in the late stage of version project.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>The last rc version will be directly merged into the beta version; features are exactly the same.</p></div>',16)])])}const m=s(o,[["render",n]]);export{f as __pageData,m as default};
